"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { type FormEvent, useState } from "react";

export default function LoginPage() {
  const router = useRouter();
  const [form, setForm] = useState({ email: "", password: "" });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function readJsonResponse(response: Response) {
    const text = await response.text();

    try {
      return text ? JSON.parse(text) : {};
    } catch {
      if (text.startsWith("<!DOCTYPE") || text.startsWith("<html")) {
        return {
          error: `Server returned HTML instead of JSON (${response.status}). Check the terminal for the real route/build error.`,
        };
      }

      return {
        error: text || `Request failed with status ${response.status}.`,
      };
    }
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setLoading(true);
    setError("");

    try {
      const response = await fetch("/api/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });

      const payload = await readJsonResponse(response);

      if (!response.ok) {
        setError(payload.error || "Unable to log in.");
        return;
      }

      router.push("/");
      router.refresh();
    } catch (fetchError) {
      setError(fetchError instanceof Error ? fetchError.message : "Unable to log in.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-slate-100 px-4 py-10">
      <form className="w-full max-w-md rounded-3xl bg-white p-8 shadow-[0_20px_60px_rgba(15,23,42,0.08)]" onSubmit={handleSubmit}>
        <p className="text-sm font-semibold uppercase tracking-[0.3em] text-blue-600">Hospital Admin</p>
        <h1 className="mt-3 text-3xl font-semibold text-slate-900">Log in to your dashboard</h1>
        <p className="mt-2 text-sm text-slate-500">Manage hospital records and add doctors without using seed data.</p>

        <div className="mt-8 space-y-4">
          <input className="w-full rounded-2xl border border-slate-200 px-4 py-3 outline-none transition focus:border-blue-500" type="email" placeholder="Admin email" value={form.email} onChange={(event) => setForm((current) => ({ ...current, email: event.target.value }))} required />
          <input className="w-full rounded-2xl border border-slate-200 px-4 py-3 outline-none transition focus:border-blue-500" type="password" placeholder="Password" value={form.password} onChange={(event) => setForm((current) => ({ ...current, password: event.target.value }))} required />
        </div>

        {error ? <p className="mt-4 text-sm font-medium text-red-600">{error}</p> : null}

        <button type="submit" disabled={loading} className="mt-6 w-full rounded-2xl bg-slate-900 px-4 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-70">
          {loading ? "Logging in..." : "Log In"}
        </button>

        <p className="mt-6 text-center text-sm text-slate-500">
          Need an account?{" "}
          <Link href="/auth/register" className="font-semibold text-blue-600 hover:text-blue-700">
            Register here
          </Link>
        </p>
      </form>
    </div>
  );
}
